'use strict';

/* eslint n/no-unsupported-features/es-builtins: ["error", {"version": ">=12.0.0"}] */

/* eslint n/no-unsupported-features/node-builtins: ["error", {"version": ">=12.0.0"}] */


// MODULES //

var vm = require( 'vm' );
var Buffer = require( 'buffer' ).Buffer;
var tape = require( 'tape' );
var NumberObject = require( '@stdlib/number/ctor' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var Uint8Array = require( '@stdlib/array/uint8' );
var ArrayBuffer = require( '@stdlib/array/buffer' );
var SharedArrayBuffer = require( '@stdlib/array/shared-buffer' );
var Proxy = require( '@stdlib/proxy/ctor' );
var Symbol = require( '@stdlib/symbol/ctor' );
var main = require( './../lib/main.js' );
var selected = require( './../lib' );
var factory = require( './../lib/factory.js' );
var configured = require( './../lib/can_use_native.js' );
var validate = require( './../lib/validate.js' );
var base = require( './../lib/base.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.strictEqual(typeof selected, 'function');

	t.end();
});

tape( 'dpbtf2: complete scalar empty validation without operand reads or dispatch', function test( t ) {
	var calls = 0;
	var probe = factory( function backend() {
		calls += 1;

		return 0;
	} );
	var trap = new Proxy( {}, {
		'get': function get() {
			throw new Error('unused operand accessed');
		}
	});
	[main, selected, probe].forEach( function each( f ) {
		[0, 2, 2147483647].forEach( function bandwidth( kd ) {
			t.strictEqual( f.ndarray('upper', 0, kd, trap, trap, trap, trap), 0, 'ndarray empty ignores all inactive metadata' );
			t.strictEqual( f('row-major', 'lower', 0, kd, trap, 1), 0, 'row-major empty allows scalar leading dimension' );
			t.strictEqual( f('column-major', 'upper', 0, kd, trap, (kd+1)), 0, 'wide empty height before native narrowing' );
		});
		t.throws( function bad() {
			f('bad', 'upper', 0, 0, trap, 1);
		}, TypeError, 'layout first' );
		t.throws( function bad() {
			f('column-major', 'U', 0, 0, trap, 1);
		}, TypeError, 'triangle validated before empty' );
		t.throws( function bad() {
			f('column-major', 'upper', 0, 2, trap, 1);
		}, RangeError, 'empty LDAB still validated' );
	});
	t.strictEqual( calls, 0, 'no backend calls' );
	t.end();
});
tape( 'dpbtf2: public invalid metadata and geometry preserve whole backing bytes', function test( t ) {
	[main, selected].forEach( function each( f ) {
		[
			['negative N', function change(a) {
				a[1]=-1;
			}, RangeError],
			['fractional N', function change(a) {
				a[1]=1.5;
			}, RangeError],
			['boxed KD', function change(a) {
				a[2]=new NumberObject(1);
			}, RangeError],
			['wide KD', function change(a) {
				a[2]=2147483648;
			}, RangeError],
			['wrong dtype', function change(a) {
				a[3]=new Int32Array(6);
			}, TypeError],
			['short full band', function change(a) {
				a[3]=new Float64Array(5);
			}, RangeError],
			['used row broadcast', function change(a) {
				a[4]=0;
			}, RangeError],
			['used column broadcast', function change(a) {
				a[5]=0;
			}, RangeError],
			['full band collision', function change(a) {
				a[5]=1;
			}, RangeError],
			['negative offset', function change(a) {
				a[6]=-1;
			}, RangeError],
			['fractional stride', function change(a) {
				a[4]=0.5;
			}, RangeError],
			['inexact product', function change(a) {
				a[4]=9007199254740991;
			}, RangeError],
			['invalid selector', function change(a) {
				a[0]='U';
			}, TypeError]
		].forEach( function invalid( spec ) {
			var before;
			var data;
			var a = ['lower', 3, 1, new Float64Array([4, 2, 10, 3, 17, 99]), 1, 2, 0];
			spec[1](a);
			data = a[3];
			before = Buffer.from( new Uint8Array(data.buffer) ).toString( 'hex' );
			t.throws( function bad() {
				f.ndarray.apply(null, a);
			}, spec[2], spec[0] );
			t.strictEqual( Buffer.from(new Uint8Array(data.buffer)).toString('hex'), before, 'all backing bytes unchanged' );
		});
	});
	t.end();
});
tape( 'dpbtf2: intrinsic brands, cross realm and current exclusive backing', function test( t ) {
	[main, selected].forEach( function each( f ) {
		var backing;
		var shared;
		var before;
		var a = new Float64Array( [4, 2, 10, 3, 17, 99] );
		Object.defineProperties( a, {
			'buffer': {
				'value': new ArrayBuffer(1)
			},
			'length': {
				'value': 0
			},
			'byteOffset': {
				'value': 99
			}
		});
		Object.defineProperty( a, Symbol.toStringTag, {
			'value': 'Int32Array'
		});
		t.strictEqual( f.ndarray('lower', 3, 1, a, 1, 2, 0), 0, 'intrinsic getters ignore shadow properties' );
		a = vm.runInNewContext( 'new Float64Array([4,2,10,3,17,99])' );
		t.strictEqual( f.ndarray('lower', 3, 1, a, 1, 2, 0), 0, 'cross-realm ordinary intrinsic Float64Array' );
		a = new Proxy( new Float64Array(6), {} );
		t.throws( function bad() {
			f.ndarray('lower', 3, 1, a, 1, 2, 0);
		}, TypeError, 'proxy cannot supply intrinsic storage' );
		if ( (typeof SharedArrayBuffer === 'function') ) {
			shared = new Float64Array( new SharedArrayBuffer(48) );
			before = Buffer.from( new Uint8Array(shared.buffer) ).toString( 'hex' );
			t.throws( function bad() {
				f.ndarray('lower', 3, 1, shared, 1, 2, 0);
			}, TypeError, 'shared backing rejected' );
			t.strictEqual( Buffer.from(new Uint8Array(shared.buffer)).toString('hex'), before, 'SAB stays untouched' );
		}
		backing = new ArrayBuffer( 48, {
			'maxByteLength': 96
		});
		if ( (typeof backing.resize === 'function') ) {
			a = new Float64Array( backing );
			a.set( [4, 2, 10, 3, 17, 99] );
			t.strictEqual( f.ndarray('lower', 3, 1, a, 1, 2, 0), 0, 'ordinary current RAB extent' );
			backing.resize(16);
			before = Buffer.from( new Uint8Array(backing) ).toString( 'hex' );
			t.throws( function bad() {
				f.ndarray('lower', 3, 1, a, 1, 2, 0);
			}, RangeError, 'shrunk active current extent' );
			t.strictEqual( Buffer.from(new Uint8Array(backing)).toString('hex'), before, 'RAB prewrite failure' );
			backing.resize(96);
			a.set( [4, 2, 10, 3, 17, 99] );
			t.strictEqual( f.ndarray('lower', 3, 1, a, 1, 2, 0), 0, 'grown current RAB extent' );
		}
	});
	t.end();
});
tape( 'dpbtf2: nonzero byte offset and unused singleton normalization', function test( t ) {
	[main, selected].forEach( function each( f ) {
		var backing = new Float64Array(12);
		var a = new Float64Array( backing.buffer, 24, 6 );
		backing.fill( 98765.25 );
		a.set( [4, 2, 10, 3, 17, 99] );
		t.strictEqual( f.ndarray('lower', 3, 1, a, 1, 2, 0), 0, 'real nonzero intrinsic byteOffset' );
		t.deepEqual( Array.prototype.slice.call(a), [2, 1, 3, 1, 4, 99], 'reference factor with star intact' );
		t.deepEqual( Array.prototype.slice.call(backing, 0, 3), [98765.25, 98765.25, 98765.25], 'prefix whole backing guard' );
		t.deepEqual( Array.prototype.slice.call(backing, 9), [98765.25, 98765.25, 98765.25], 'suffix whole backing guard' );
		a = new Float64Array( [4] );
		t.strictEqual( f.ndarray('upper', 1, 0, a, 9007199254740991, -9007199254740991, 0), 0, 'normalize unused wide singleton metadata before backend' );
		t.strictEqual( a[0], 2, 'singleton output' );
	});
	t.end();
});
tape( 'dpbtf2: private error conversion and configured defensive routing', function test( t ) {
	var fallbackCalls = 0;
	var nativeCalls = 0;
	var eligible = configured(4, 4);
	var a = new Float64Array( [4, 2, 10, 3, 17, 99] );
	var f = factory( function backend() {
		nativeCalls += 1;

		return 0;
	}, function no() {
		return false;
	}, function fallback() {
		fallbackCalls += 1;

		return base.apply(null, arguments);
	} );
	t.strictEqual( f.ndarray('lower', 3, 1, a, 1, 2, 0), 0, 'forced-false predicate routes real fallback before native' );
	t.strictEqual( nativeCalls, 0, 'no native dispatch in forced branch probe' );
	t.strictEqual( fallbackCalls, 1, 'fallback executed; no huge backing allocation is claimed' );
	[-1, Infinity, 0.5, 4].forEach( function error( status ) {
		var g = factory( function backend() {
			return status;
		} );
		var b = new Float64Array( [4, 2, 10, 3, 17, 99] );
		t.throws( function bad() {
			g.ndarray('lower', 3, 1, b, 1, 2, 0);
		}, RangeError, 'private status converted to error' );
		t.deepEqual( Array.prototype.slice.call(b), [4, 2, 10, 3, 17, 99], 'injected prewrite private error leaves data intact' );
	});
	t.throws( function bad() {
		configured(0, 4);
	}, RangeError, 'unknown configured width rejected' );
	t.strictEqual( eligible(121, 2, 1, null, 1, 2147483648, 0), false, 'wide active metadata excludes LP32 bridge' );
	t.strictEqual( configured(8, 4)(121, 3, 2, null, 1, 2147483648, 0), false, 'independent B32 helper width predicate' );
	t.strictEqual( configured(8, 8)(121, 3, 2, null, 1, 2147483648, 0), true, 'independent configured wide predicate; no huge allocation' );
	t.strictEqual( eligible.trip(1, 9007199254740991), true, 'singleton helper normalizes stride' );
	t.strictEqual( eligible.trip(2147483642, 1), true, 'conservative unit terminal predicate' );
	t.strictEqual( eligible.trip(2147483643, 1), false, 'unit terminal bound excludes native call' );
	t.strictEqual( eligible.trip(2, 1073741823), false, 'nonunit terminal predicate excludes native call' );
	t.strictEqual( validate.sum(-9007199254740991, 9007199254740991), 0, 'exact opposite sign safe sum' );
	t.throws( function bad() {
		validate.sum(9007199254740991, 1);
	}, RangeError, 'sum checked before inexact arithmetic' );
	t.throws( function bad() {
		validate.product(2, 9007199254740991);
	}, RangeError, 'product checked before inexact arithmetic' );
	t.end();
});
